    const Game = {
      playerName: "",
      petId: "dog",
      events: [],
      currentIndex: 0,
      correctCount: 0,
      wrongCount: 0,
      hearts: 3
    };

    function showScreen(id) {
      document.querySelectorAll('.screen-view').forEach(s => s.classList.remove('active'));
      const el = document.getElementById(id);
      if (el) el.classList.add('active');
      window.scrollTo(0, 0);
    }

    function goToSelectScreen() {
      SoundFX.init();
      const input = document.getElementById('player-name-input');
      Game.playerName = input.value.trim() || "科教館小學員";
      showScreen('screen-select');
    }

    function shuffleArray(array) {
      const arr = [...array];
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
      }
      return arr;
    }

    function selectPet(petId) {
      SoundFX.init();
      Game.petId = petId;
      const allQuestions = QUIZ_DATABASE[petId] || QUIZ_DATABASE.dog;
      // 從 35 題豐富題庫中，每次遊玩隨機抽取 7 關考驗
      Game.events = shuffleArray(allQuestions).slice(0, 7);
      Game.currentIndex = 0;
      Game.correctCount = 0;
      Game.wrongCount = 0;
      Game.hearts = 3;

      const avatars = { dog: "🐕", cat: "🐈", rabbit: "🐇", hamster: "🐹" };
      document.getElementById('ui-pet-avatar').innerText = avatars[petId];

      renderQuestion();
      showScreen('screen-game');
    }

    function adjustCardHeight() {
      const scene = document.querySelector('.card-scene');
      const flipper = document.getElementById('card-flipper');
      const front = document.querySelector('.card-front');
      const back = document.querySelector('.card-back');
      if (!scene || !flipper || !front) return;

      scene.style.minHeight = '';
      flipper.style.minHeight = '';
      front.style.minHeight = '';
      if (back) back.style.minHeight = '';

      const frontH = front.scrollHeight;
      const backH = back ? back.scrollHeight : 0;
      const isMobile = window.innerWidth <= 768;
      const baseMin = isMobile ? 440 : 465;
      const targetH = Math.max(baseMin, frontH, backH);

      scene.style.minHeight = targetH + 'px';
      flipper.style.minHeight = targetH + 'px';
      front.style.minHeight = targetH + 'px';
      if (back) back.style.minHeight = targetH + 'px';
    }

    function renderQuestion() {
      const flipper = document.getElementById('card-flipper');
      flipper.classList.remove('is-flipped');

      const ev = Game.events[Game.currentIndex];
      document.getElementById('ui-pet-year').innerHTML = zhuyinify(`第 ${ev.year} 年`);
      document.getElementById('ui-q-tag').innerHTML = zhuyinify(`第 ${Game.currentIndex + 1} / ${Game.events.length} 關考驗`);
      document.getElementById('ui-q-emoji').innerText = ev.emoji;
      
      const qTextEl = document.getElementById('ui-q-text');
      qTextEl.innerHTML = zhuyinify(ev.text);
      if (ev.text.length >= 26) {
        qTextEl.classList.add('is-long');
      } else {
        qTextEl.classList.remove('is-long');
      }

      // 更新守護愛心顯示
      renderHearts();

      const wrapper = document.getElementById('ui-options-wrapper');
      wrapper.innerHTML = "";

      if (ev.type === "ox") {
        wrapper.className = "ox-container";
        wrapper.innerHTML = `
          <button class="btn-ox btn-ox-correct" onclick="handleAnswer(true)">
            <span class="ox-icon">⭕</span>
            <span class="btn-ox-text">${zhuyinify("是的 / 做得對")}</span>
          </button>
          <button class="btn-ox btn-ox-wrong" onclick="handleAnswer(false)">
            <span class="ox-icon">❌</span>
            <span class="btn-ox-text">${zhuyinify("不對 / 不可以")}</span>
          </button>
        `;
      } else if (ev.type === "pic") {
        wrapper.className = "pic-choice-container";
        ev.options.forEach(opt => {
          const btn = document.createElement('button');
          btn.className = "btn-pic-card";
          btn.innerHTML = `
            <div class="pic-emoji">${opt.emoji}</div>
            <div class="pic-label">${zhuyinify(opt.label)}</div>
          `;
          btn.onclick = () => handleAnswer(opt.isCorrect);
          wrapper.appendChild(btn);
        });
      }

      adjustCardHeight();
    }

    function renderHearts(lostIndex = -1) {
      for (let i = 0; i < 3; i++) {
        const heart = document.getElementById(`heart-${i}`);
        if (!heart) continue;
        if (i < Game.hearts) {
          heart.className = "heart-item active";
          heart.innerText = "❤️";
        } else if (i === lostIndex) {
          heart.className = "heart-item breaking";
          heart.innerText = "❤️";
          setTimeout(() => {
            heart.className = "heart-item lost";
            heart.innerText = "💔";
          }, 850);
        } else {
          heart.className = "heart-item lost";
          heart.innerText = "💔";
        }
      }
    }

    function triggerLossAnimation() {
      const floatBadge = document.getElementById('ui-float-penalty');
      if (floatBadge) {
        floatBadge.classList.remove('show');
        void floatBadge.offsetWidth;
        floatBadge.classList.add('show');
      }
      const cardScene = document.querySelector('.card-scene');
      if (cardScene) {
        cardScene.classList.add('shake');
        setTimeout(() => cardScene.classList.remove('shake'), 500);
      }
    }

    function handleAnswer(userChoice) {
      SoundFX.init();
      const ev = Game.events[Game.currentIndex];
      let isCorrect = false;

      if (ev.type === "ox") {
        isCorrect = (userChoice === ev.correctAnswer);
      } else {
        isCorrect = userChoice;
      }

      const resTitle = document.getElementById('ui-result-title');
      const fatalBadgeWrap = document.getElementById('ui-fatal-badge-wrap');
      const btnNext = document.getElementById('ui-btn-next');

      if (isCorrect) {
        Game.correctCount++;
        SoundFX.playCorrectChime();
        resTitle.className = "result-announcement result-correct";
        resTitle.innerHTML = zhuyinify("✅ 答對了！太棒了！");
        fatalBadgeWrap.innerHTML = "";
        btnNext.innerHTML = zhuyinify("下一題 ➔");
        btnNext.onclick = nextQuestion;
      } else {
        Game.wrongCount++;
        const lostIndex = Game.hearts - 1;
        Game.hearts = Math.max(0, Game.hearts - 1);
        resTitle.className = "result-announcement result-wrong";
        resTitle.innerHTML = zhuyinify("❌ 哎呀！這是不對的喔！");

        if (Game.petId === 'cat') {
          SoundFX.playCatMeow();
        } else if (Game.petId === 'dog') {
          SoundFX.playDogWhimper();
        } else if (Game.petId === 'rabbit') {
          SoundFX.playRabbitSqueak();
        } else if (Game.petId === 'hamster') {
          SoundFX.playHamsterSqueak();
        }

        renderHearts(lostIndex);
        triggerLossAnimation();

        if (Game.hearts <= 0) {
          fatalBadgeWrap.innerHTML = `
            <div class="fatal-warning-badge">
              ${zhuyinify("🚨 警告：累積失去 3 顆守護心！毛孩生命值歸零不幸夭折！")}
            </div>
          `;
          btnNext.innerHTML = zhuyinify("🚨 毛孩死亡，查看不及格證書 ➔");
          btnNext.onclick = triggerFatalityScreen;
        } else {
          fatalBadgeWrap.innerHTML = `
            <div class="fatal-warning-badge">
              ${zhuyinify(`⚠️ 扣除 1 顆守護心！剩餘：${Game.hearts} 顆（失去 3 顆心寵物將離世）`)}
            </div>
          `;
          btnNext.innerHTML = zhuyinify("記取教訓，下一題 ➔");
          btnNext.onclick = nextQuestion;
        }
      }

      document.getElementById('ui-vet-tip').innerHTML = zhuyinify(ev.vetTip);
      document.getElementById('card-flipper').classList.add('is-flipped');
      adjustCardHeight();
    }

    function nextQuestion() {
      Game.currentIndex++;
      if (Game.currentIndex < Game.events.length) {
        renderQuestion();
      } else {
        showCertificate();
      }
    }

    function triggerFatalityScreen() {
      const petNames = { dog: "米克斯汪汪", cat: "虎斑喵喵", rabbit: "垂耳兔兔", hamster: "三線倉鼠" };
      document.getElementById('ui-fatal-player').innerText = Game.playerName;
      document.getElementById('ui-fatal-pet').innerText = petNames[Game.petId] || "寵物夥伴";
      showScreen('screen-fatal');
    }

    // 精準對齊愛心評級：
    // 剩 3 心 (0 錯) -> S 級
    // 剩 2 心 (少 1 心) -> A 級
    // 剩 1 心 (少 2 心) -> B 級
    function showCertificate() {
      const petNames = { dog: "米克斯汪汪", cat: "虎斑喵喵", rabbit: "垂耳兔兔", hamster: "三線倉鼠" };
      document.getElementById('ui-cert-player').innerText = Game.playerName;
      document.getElementById('ui-cert-pet').innerText = petNames[Game.petId];

      let grade = "S", title = "🌟 金牌典範小獸醫";
      let advice = "太優秀了！生活改變，毛孩永遠是最好的家人！記得定期打預防針、植晶片，生病溫柔照顧，守護一生不離不棄！";

      if (Game.hearts === 2) {
        grade = "A";
        title = "🏅 愛心優良小主人";
        advice = "非常棒！你具備正確基礎醫學常識！未來飼養請維持定期清潔、提供充足乾淨開水，給毛孩最安全的家園！";
      } else if (Game.hearts === 1) {
        grade = "B";
        title = "🌱 實習成長小主人";
        advice = "養寵物不是只有好玩，更要準備好時間與醫療耐心！遇到困難一定要跟家人與獸醫商量，絕不能輕易放棄生命喔！";
      }

      document.getElementById('ui-cert-grade').innerText = grade;
      document.getElementById('ui-cert-title').innerText = title;
      document.getElementById('ui-cert-advice').innerText = advice;

      showScreen('screen-cert');
    }

    function confirmQuitToHome() {
      if (confirm("要重新選擇動物夥伴並返回首頁嗎？")) {
        resetToHome();
      }
    }

    function resetToHome() {
      showScreen('screen-welcome');
    }

    // HTML5 Canvas 實體證書 PNG 下載生成器 (高解析度)
    function downloadCertificateImage() {
      const canvas = document.getElementById('certCanvas');
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      const w = canvas.width;
      const h = canvas.height;

      // 1. 底色與法式烘焙金邊
      ctx.fillStyle = '#fefbf3';
      ctx.fillRect(0, 0, w, h);

      ctx.strokeStyle = '#b45309';
      ctx.lineWidth = 10;
      ctx.strokeRect(20, 20, w - 40, h - 40);

      ctx.strokeStyle = '#fde68a';
      ctx.lineWidth = 3;
      ctx.strokeRect(32, 32, w - 64, h - 64);

      // 2. 標題與印鑑文字
      ctx.textAlign = 'center';
      
      ctx.fillStyle = '#78350f';
      ctx.font = 'bold 24px sans-serif';
      ctx.fillText('國立臺灣大學獸醫學系 ✕ 國立臺灣科學教育館 聯合頒發', w / 2, 78);

      ctx.fillStyle = '#451a03';
      ctx.font = '900 42px sans-serif';
      ctx.fillText('🏆 特派良善飼主榮譽結業證書', w / 2, 138);

      ctx.strokeStyle = '#fde68a';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(100, 165);
      ctx.lineTo(w - 100, 165);
      ctx.stroke();

      const petNames = { dog: "米克斯汪汪", cat: "虎斑喵喵", rabbit: "垂耳兔兔", hamster: "三線倉鼠" };
      const pet = petNames[Game.petId] || "寵物夥伴";
      const name = Game.playerName || "小學員";

      ctx.fillStyle = '#292524';
      ctx.font = 'bold 28px sans-serif';
      ctx.fillText(`茲證明小學員 【 ${name} 】 成功通過生命守護考驗，`, w / 2, 225);
      ctx.fillText(`以滿滿愛心承諾守護夥伴 【 ${pet} 】 一生不離不棄！`, w / 2, 270);

      // 3. 等級徽章區塊
      const grade = document.getElementById('ui-cert-grade').innerText || 'S';
      const title = document.getElementById('ui-cert-title').innerText || '金牌典範小獸醫';
      
      ctx.fillStyle = '#fffbeb';
      ctx.fillRect(w / 2 - 200, 310, 400, 120);
      ctx.strokeStyle = '#fde68a';
      ctx.lineWidth = 4;
      ctx.strokeRect(w / 2 - 200, 310, 400, 120);

      ctx.fillStyle = '#b45309';
      ctx.font = '900 52px sans-serif';
      ctx.fillText(`等級 ${grade}`, w / 2, 365);

      ctx.fillStyle = '#78350f';
      ctx.font = 'bold 24px sans-serif';
      ctx.fillText(title, w / 2, 405);

      // 4. 衛教叮嚀小字
      ctx.fillStyle = '#78350f';
      ctx.font = 'bold 20px sans-serif';
      ctx.fillText('「想養只是一時喜歡，準備好是一生的承諾」', w / 2, 475);
      ctx.font = '18px sans-serif';
      ctx.fillStyle = '#57534e';
      ctx.fillText('請持續維持定期預防注射、晶片登記與細心醫療照護。', w / 2, 510);

      const today = new Date().toLocaleDateString('zh-TW', { year: 'numeric', month: 'long', day: 'numeric' });
      ctx.font = '18px sans-serif';
      ctx.fillStyle = '#78716c';
      ctx.fillText(`核發日期：${today}`, w / 2, 580);

      // 紅色鋼印模擬
      ctx.save();
      ctx.strokeStyle = '#dc2626';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(w - 180, 560, 55, 0, Math.PI * 2);
      ctx.stroke();
      ctx.fillStyle = '#dc2626';
      ctx.font = 'bold 16px sans-serif';
      ctx.fillText('臺大獸醫', w - 180, 555);
      ctx.fillText('衛教合格', w - 180, 580);
      ctx.restore();

      const imageURL = canvas.toDataURL('image/png');
      const downloadLink = document.createElement('a');
      downloadLink.download = `守護榮譽證書_${name}.png`;
      downloadLink.href = imageURL;
      document.body.appendChild(downloadLink);
      downloadLink.click();
      document.body.removeChild(downloadLink);
    }

    // URL 參數路由支援
    const params = new URLSearchParams(window.location.search);
    const viewParam = params.get('view');
    const petParam = params.get('pet') || 'dog';
    const qIndexParam = parseInt(params.get('q') || '0', 10);
    const flipParam = params.get('flip') === '1';
    const fatalParam = params.get('fatal') === '1';
    const lossParam = params.get('loss') === '1';

    if (viewParam) {
      if (viewParam === 'screen-game') {
        selectPet(petParam);
        const exactQ = params.get('exact_q');
        if (exactQ) {
          const list = QUIZ_DATABASE[petParam] || QUIZ_DATABASE.dog;
          const target = list.find(q => q.text.includes(exactQ));
          if (target) {
            Game.events = [target];
            Game.currentIndex = 0;
          }
        } else {
          Game.currentIndex = qIndexParam;
        }
        if (fatalParam) {
          Game.wrongCount = 2;
          Game.hearts = 1;
        }
        renderQuestion();
        if (lossParam) {
          handleAnswer(true);
        } else if (flipParam) {
          const ev = Game.events[Game.currentIndex];
          const ansToTrigger = (ev.type === 'ox') ? ev.correctAnswer : true;
          handleAnswer(ansToTrigger);
        }
      } else if (viewParam === 'screen-fatal') {
        selectPet(petParam);
        triggerFatalityScreen();
      } else if (viewParam === 'screen-cert') {
        selectPet(petParam);
        Game.correctCount = 7;
        showCertificate();
      } else {
        showScreen(viewParam);
      }
    }
  